pub struct MdmaService<B: Backend> {
    backend: Arc<B>,
    registry: Arc<Registry<B>>,
    backend_name: &'static str,
    shutdown: Option<WeakShutdownGuard>,
    power: Option<(watch::Receiver<PowerStatus>, DegradedLimits)>,
    routes: Option<crate::federation::routing::Router>,
}

impl<B: Backend> MdmaService<B> {
    pub fn new(backend: Arc<B>, mut registry: Registry<B>, backend_name: &'static str) -> Self {
        registry.bind_execution_backend(&*backend);
        Self { backend, registry: Arc::new(registry), backend_name, shutdown: None, power: None, routes: None }
    }

    /// Use the same shutdown manager as the listener's graceful Executor.
    /// Reject new generations during drain and track blocking inference workers.
    #[must_use]
    pub fn with_shutdown_guard(mut self, guard: WeakShutdownGuard) -> Self {
        self.shutdown = Some(guard);
        self
    }

    /// Follow the power watcher's state: smaller limits while `Degraded`,
    /// no new generations while `Critical`. Without it, always `Serving`.
    #[must_use]
    pub fn with_power(mut self, status: watch::Receiver<PowerStatus>, limits: DegradedLimits) -> Self {
        self.power = Some((status, limits));
        self
    }

    pub(crate) fn federation_inventory(&self) -> Arc<dyn crate::federation::inventory::Inventory>
    where
        B: Send + Sync + 'static,
        B::Buf: Send + Sync,
    {
        Arc::new(crate::federation::inventory::Native {
            registry: self.registry.clone(),
            shutdown: self.shutdown.clone(),
            power: self.power.clone(),
        })
    }

    pub(crate) fn federation_executor(&self) -> Arc<dyn crate::federation::execution::Executor>
    where
        B: Send + Sync + 'static,
        B::Buf: Send + Sync,
    {
        Arc::new(crate::federation::execution::Native {
            backend: self.backend.clone(),
            // Dedicated bounded federation Laya request scratch; ordinary
            // Laya/weights remain outside the decoder's shared tensor budget.
            decision_budget: crate::memory::NativeMemoryBudget::new(128 * 1024 * 1024),
            inventory: crate::federation::inventory::Native {
                registry: self.registry.clone(),
                shutdown: self.shutdown.clone(),
                power: self.power.clone(),
            },
        })
    }

    pub(crate) fn federation_local_names(&self) -> Vec<String> {
        self.registry.names().into_iter().map(str::to_owned).collect()
    }
    pub(crate) fn set_federation_router(&mut self, router: crate::federation::routing::Router) {
        self.routes = Some(router);
    }

    fn power_status(&self) -> PowerStatus {
        self.power.as_ref().map(|(rx, _)| *rx.borrow()).unwrap_or_default()
    }

    fn shutting_down(&self) -> bool {
        self.shutdown.as_ref().is_some_and(|guard| guard.cancelled().now_or_never().is_some())
    }

    /// Lifecycle/power readiness; memory admission depends on the request size.
    fn ready(&self) -> bool {
        !self.shutting_down() && matches!(self.power_status().state, ServerState::Serving | ServerState::Degraded)
    }

    fn lookup(&self, name: &str) -> Result<&Loaded<B>, Status> {
        let loaded = self.registry.get(name).ok_or_else(|| Status::not_found(format!("no model named {name:?}; available: {}", self.registry.names().join(", "))))?;
        if let Entry::Unavailable(model) = &loaded.entry {
            return Err(Status::resource_exhausted(format!("model {:?} is not loaded: {}; free memory and restart the server to retry", loaded.name, model.reason)));
        }
        Ok(loaded)
    }

    /// The admission decision every request shares: refused while
    /// draining or critical, capped while degraded. Returns the
    /// (max_tokens, n_ctx) to run with; `n_ctx` is the caller's cap.
    fn admit(&self, prompt_tokens: impl FnOnce() -> Result<usize, Status>, max_tokens: usize, n_ctx: usize) -> Result<(usize, usize), Status> {
        if self.shutting_down() {
            return Err(Status::unavailable("server is shutting down"));
        }
        // Read once per request; a state change mid-stream does not cut it off.
        let power = self.power_status();
        match power.state {
            ServerState::Serving => Ok((max_tokens, n_ctx)),
            ServerState::Degraded => {
                let limits = self.power.as_ref().map(|(_, limits)| *limits).unwrap_or_default();
                let n_ctx = n_ctx.min(limits.n_ctx);
                let prompt_tokens = prompt_tokens()?;
                if prompt_tokens > n_ctx {
                    return Err(Status::resource_exhausted(format!(
                        "server is degraded (on battery): prompt is {prompt_tokens} tokens, limit {n_ctx}"
                    )));
                }
                let remaining = n_ctx - prompt_tokens;
                if remaining == 0 && max_tokens > 0 {
                    return Err(Status::resource_exhausted(format!(
                        "server is degraded (on battery): prompt fills the {n_ctx}-token context; no room for output"
                    )));
                }
                Ok((max_tokens.min(limits.max_tokens).min(remaining), n_ctx))
            }
            ServerState::Critical => {
                let percent = power.reading.and_then(|r| r.battery_percent);
                let at = percent.map(|p| format!(" at {p}%")).unwrap_or_default();
                Err(Status::unavailable(format!("server is on battery{at}; not accepting generations")))
            }
            ServerState::Draining => Err(Status::unavailable("server is shutting down")),
        }
    }
}

/// Missing fields use independent defaults; explicit zero values are preserved.
fn sampler_config_from_proto(cfg: Option<proto::SamplerConfig>) -> SamplerConfig {
    let defaults = SamplerConfig::default();
    let Some(cfg) = cfg else {
        return defaults;
    };
    SamplerConfig {
        temperature: cfg.temperature.unwrap_or(defaults.temperature),
        top_p: cfg.top_p.unwrap_or(defaults.top_p),
        min_p: cfg.min_p.unwrap_or(defaults.min_p),
        repetition_penalty: cfg.repetition_penalty.unwrap_or(defaults.repetition_penalty),
        repetition_window: cfg.repetition_window.map_or(defaults.repetition_window, |w| w as usize),
    }
}

fn token_response(t: GeneratedToken) -> SynthesizeResponse {
    SynthesizeResponse { token_id: t.token_id, text: t.text }
}

#[expect(clippy::needless_pass_by_value, reason = "map_err adapter")]
fn native_status(error: crate::backend::Error) -> Status {
    if error.is_memory_exhausted() {
        return Status::resource_exhausted(error.to_string());
    }
    match error {
        crate::backend::Error::ContextLimit { .. } =>
            Status::resource_exhausted(error.to_string()),
        _ => Status::internal(error.to_string()),
    }
}

pub(crate) type TokenStream = Pin<Box<dyn Stream<Item = Result<SynthesizeResponse, Status>> + Send + Sync + 'static>>;

impl<B> Mdma for MdmaService<B>
where
    B: Backend + Send + Sync + 'static,
    B::Buf: Send + Sync,
{
    type SynthesizeStream = TokenStream;

    async fn synthesize(&self, mut req: Request<SynthesizeRequest>) -> Result<Response<Self::SynthesizeStream>, Status> {
        if let Some(router) = self.routes.as_ref().filter(|router| router.contains(&req.get_ref().model)) {
            let (cap, _) = self.admit(|| Ok(0), req.get_ref().max_tokens as usize, usize::MAX)?;
            req.get_mut().max_tokens = cap as u32;
            return router.synthesize(req).await;
        }
        let loaded = self.lookup(&req.get_ref().model)?;
        let max_tokens = req.get_ref().max_tokens as usize;
        match &loaded.entry {
            Entry::Decoder(decoder) => {
                let req = req.into_inner();
                let sampler_config = sampler_config_from_proto(req.sampler);
                let n_ctx = decoder.n_ctx.min(decoder.model.config().n_ctx);
                let (max_tokens, n_ctx) = self.admit(
                    || decoder.tokenizer.try_encode(&req.prompt).map(|ids| ids.len()).map_err(native_status),
                    max_tokens, n_ctx,
                )?;
                let guard = self.shutdown.clone().map(WeakShutdownGuard::upgrade);
                let session = Session::new(self.backend.clone(), decoder.model.clone(), decoder.tokenizer.clone(), sampler_config, n_ctx);
                // Dropping the HTTP/2 response body cancels the session's worker.
                let stream = session
                    .generate_guarded(&req.prompt, max_tokens, CancellationToken::new(), guard)
                    .map_err(native_status)?;
                let mapped = stream.map(|item| item.map(token_response).map_err(native_status));
                Ok(Response::new(Box::pin(mapped)))
            }
            Entry::Upstream(upstream) => {
                let (max_tokens, _) = self.admit(|| Ok(0), max_tokens, usize::MAX)?;
                let guard = self.shutdown.clone().map(WeakShutdownGuard::upgrade);
                req.get_mut().max_tokens = max_tokens as u32;
                let response = upstream.synthesize(req).await?;
                Ok(response.map(|stream| {
                    Box::pin(stream.map(move |item| {
                        let _guard = &guard;
                        item
                    })) as TokenStream
                }))
            }
            Entry::Laya(_) => Err(Status::invalid_argument(format!("model {:?} answers typed decisions; use Decide", loaded.name))),
            Entry::Unavailable(_) => Err(Status::resource_exhausted("model is not loaded")),
        }
    }

    async fn decide(&self, req: Request<DecideRequest>) -> Result<Response<DecideResponse>, Status> {
        if let Some(router) = self.routes.as_ref().filter(|router| router.contains(&req.get_ref().model)) {
            self.admit(|| Ok(0), 0, usize::MAX)?;
            return router.decide(req).await;
        }
        let loaded = self.lookup(&req.get_ref().model)?;
        let predictor = match &loaded.entry {
            Entry::Upstream(upstream) => {
                self.admit(|| Ok(0), 0, usize::MAX)?;
                let _guard = self.shutdown.clone().map(WeakShutdownGuard::upgrade);
                return upstream.decide(req).await;
            }
            Entry::Laya(predictor) => predictor,
            Entry::Decoder(_) => return Err(Status::invalid_argument(format!("model {:?} generates text; use Synthesize", loaded.name))),
            Entry::Unavailable(_) => return Err(Status::resource_exhausted("model is not loaded")),
        };
        self.admit(|| Ok(0), 0, usize::MAX)?;
        let req = req.into_inner();
        let state: serde_json::Value = serde_json::from_str(&req.state_json).map_err(|e| Status::invalid_argument(format!("state_json: {e}")))?;
        let questions = serde_json::from_str::<serde_json::Value>(&req.questions_json)
            .map_err(|e| Status::invalid_argument(format!("questions_json: {e}")))?;
        let serde_json::Value::Object(questions) = questions else {
            return Err(Status::invalid_argument("questions_json must be an object keyed by question id"));
        };
        let predictor = predictor.clone();
        let guard = self.shutdown.clone().map(WeakShutdownGuard::upgrade);
        let result = tokio::task::spawn_blocking(move || {
            let _guard = guard;
            predictor.predict(&state, &questions)
        })
        .await
        .map_err(|e| Status::internal(e.to_string()))?
        .map_err(|e| match e {
            crate::laya::Error::Question(_) => Status::invalid_argument(e.to_string()),
            other => Status::internal(other.to_string()),
        })?;
        Ok(Response::new(DecideResponse { result_json: result.to_string() }))
    }

    async fn introspect(&self, req: Request<IntrospectRequest>) -> Result<Response<IntrospectResponse>, Status> {
        let power = self.power_status();
        let state = if self.shutting_down() { ServerState::Draining } else { power.state };
        let ready = self.ready();
        let mut models = Vec::with_capacity(self.registry.names().len());
        for loaded in self.registry.iter() {
            let (backend, architecture, n_ctx, upstream, model_ready) = match &loaded.entry {
                Entry::Decoder(d) => (self.backend_name.to_string(), d.architecture.clone(), d.n_ctx.min(d.model.config().n_ctx), String::new(), ready),
                Entry::Laya(p) => ("cpu".to_string(), p.architecture().to_string(), p.max_len(), String::new(), ready),
                Entry::Upstream(u) => match u.introspect(req.metadata()).await {
                    Ok(remote) => (remote.backend, remote.architecture, remote.n_ctx as usize, u.url().to_string(), ready && remote.ready),
                    Err(_) => ("upstream".to_string(), String::new(), 0, u.url().to_string(), false),
                },
                Entry::Unavailable(model) => (self.backend_name.to_string(), model.architecture.clone(), model.n_ctx, String::new(), false),
            };
            models.push(ModelStatus {
                name: loaded.name.clone(),
                kind: loaded.kind.name().to_string(),
                backend,
                architecture,
                n_ctx: n_ctx as u32,
                ready: model_ready,
                weight_bytes: loaded.weight_bytes,
                upstream,
            });
        }
        if let Some(router) = &self.routes {
            models.extend(router.statuses(&req, ready));
        }
        let default = self.registry.default_model();
        let default_status = models.iter().find(|m| m.name == default.name);
        let state_name = if state == ServerState::Serving && self.registry.iter().any(|model| matches!(model.entry, Entry::Unavailable(_))) {
            "degraded".to_string()
        } else {
            state.name().to_ascii_lowercase()
        };
        Ok(Response::new(IntrospectResponse {
            ready: ready && self.registry.iter().any(|model| !matches!(model.entry, Entry::Unavailable(_))),
            model_architecture: default_status.map(|m| m.architecture.clone()).unwrap_or_default(),
            backend: self.backend_name.to_string(),
            server_state: state_name,
            on_battery: power.reading.is_some_and(|r| r.on_battery),
            battery_percent: power.reading.and_then(|r| r.battery_percent).map_or(-1, i32::from),
            gpu_power_limit_mw: power.reading.and_then(|r| r.gpu).map_or(0, |g| g.limit_mw),
            gpu_power_default_mw: power.reading.and_then(|r| r.gpu).map_or(0, |g| g.default_mw),
            default_model: default.name.clone(),
            models,
        }))
    }
}

